// Ingredient-driven appearance, shared by bowls, oven, decorating and serving.
const foodClamp=(n,a=0,b=1)=>Math.max(a,Math.min(b,n));
function foodBlend(a,b,t){t=foodClamp(t);const parse=c=>[1,3,5].map(i=>parseInt(c.slice(i,i+2),16));const x=parse(a),y=parse(b);return '#'+x.map((v,i)=>Math.round(v+(y[i]-v)*t).toString(16).padStart(2,'0')).join('')}
function ingredientVolume(n,v){return v*({Flour:.25,Sugar:.25,Cocoa:.25,'Chocolate chips':.25,Butter:.25,Egg:.2,Milk:.25,Vanilla:.02,'Lemon juice':.06,Honey:.06,Salt:.004,'Baking soda':.005,'Baking powder':.01,Cinnamon:.015}[n]||.02)}
function batterAppearance(kind,s){const a=kind==='dry'?s.dryAmounts||{}:kind==='wet'?s.wetAmounts||{}:s.combined?s.wetAmounts||s.amounts:s.amounts;const get=n=>a[n]||0,total=Object.entries(a).reduce((t,[n,v])=>t+ingredientVolume(n,v),0);const dry=ingredientVolume('Flour',get('Flour'))+ingredientVolume('Cocoa',get('Cocoa'))+.3*ingredientVolume('Sugar',get('Sugar'));const liquid=ingredientVolume('Milk',get('Milk'))+ingredientVolume('Egg',get('Egg'))+.7*ingredientVolume('Butter',get('Butter'))+ingredientVolume('Lemon juice',get('Lemon juice'))+ingredientVolume('Honey',get('Honey'));const cocoa=get('Cocoa')*.25,egg=get('Egg')*.2,butter=get('Butter')*.25,milk=get('Milk')*.25;let color=kind==='dry'?'#f4ead5':'#f6ead1';color=foodBlend(color,'#e6c56f',foodClamp((egg+butter*.6)/(total+.05))*.65);color=foodBlend(color,'#fff7ed',foodClamp(milk/(total+.05))*.7);color=foodBlend(color,'#77503a',cocoa/(cocoa+(total-cocoa)*.16+.03));color=foodBlend(color,'#ad8055',foodClamp(get('Cinnamon')*.15+get('Vanilla')*.035+get('Honey')*.02));let progress=kind==='dry'?s.dryStirs||0:kind==='wet'&&!s.combined?s.wetStirs||0:s.foldStirs??s.mix/s.r.mix??0;const all=[...s.r.dry,...s.r.wet],expected=Object.fromEntries(all.map(([n,v])=>[n,v]));const liquidOf=b=>Object.entries(b).reduce((t,[n,v])=>t+(['Milk','Egg','Butter','Lemon juice','Honey'].includes(n)?ingredientVolume(n,v)*(n==='Butter'?.7:1):0),0),dryOf=b=>ingredientVolume('Flour',b.Flour||0)+ingredientVolume('Cocoa',b.Cocoa||0)+.3*ingredientVolume('Sugar',b.Sugar||0);const moisture=kind==='dry'?0:kind==='wet'&&!s.combined?2:(liquid/(dry+.03))/Math.max(.05,liquidOf(expected)/(dryOf(expected)+.03));const lumps=foodClamp(1-progress)+(kind==='combined'||s.combined?foodClamp(1-(s.dryStirs??1))*.3:0);const texture=total<.001?'empty':kind==='dry'?(progress<.85?'patchy powder':'fine dry mixture'):kind==='wet'&&!s.combined?(progress<.85?'butter and egg streaks':'smooth liquid'):moisture>1.4?'runny and glossy':moisture<.65?'thick and clumpy':lumps>.15?'floury streaks':'smooth batter';return {kind,combined:!!s.combined,a,total,color,progress,lumps,moisture,texture,empty:total<.001,chips:Math.min(30,Math.round(get('Chocolate chips')*4)),butter,egg,milk,cocoa,rx:35+foodClamp(total/2)*89,ry:10+foodClamp(total/2)*25,cy:121-foodClamp(total/2)*14}}
function batterTextureSvg(v){if(v.empty)return '';const id='foodclip'+illustrationId++,x=(i,k)=>180+Math.cos(i*2.399963)*v.rx*(.18+(i*13%70)/100),y=(i,k)=>v.cy+Math.sin(i*2.399963)*v.ry*(.2+(i*11%65)/100);let marks='';if(v.kind==='dry'){for(let i=0;i<38;i++)marks+=`<ellipse cx="${x(i)}" cy="${y(i)}" rx="${i%3+1}" ry=".9" fill="${foodBlend(v.color,'#8c6e4c',.23)}" opacity=".45"/>`;if(v.lumps>.15){for(let i=0;i<8;i++)marks+=`<ellipse cx="${x(i)}" cy="${y(i)}" rx="${9+v.lumps*7}" ry="${3+v.lumps*4}" fill="${i%2&&v.cocoa?'#9a7254':'#fff6e1'}" opacity="${foodClamp(v.lumps)*.8}"/>`}}
else{if(v.moisture>1.4||v.kind==='wet')marks+=`<ellipse cx="${180-v.rx*.2}" cy="${v.cy-v.ry*.2}" rx="${v.rx*.58}" ry="${v.ry*.52}" fill="#fff9e1" opacity=".22"/><path d="M${180-v.rx*.65} ${v.cy+v.ry*.22}q${v.rx*.55} ${v.ry*.55} ${v.rx*1.15} 0" fill="none" stroke="#fff9e3" stroke-width="2.5" opacity=".4"/>`;if(v.lumps>.1){for(let i=0;i<Math.ceil(v.lumps*9);i++){const chunky=v.moisture<.65;marks+=`<ellipse cx="${x(i)}" cy="${y(i)}" rx="${chunky?12:8}" ry="${chunky?6:3}" fill="#fbefd5" opacity="${foodClamp(v.lumps)*.9}"/>`}}if(v.kind==='wet'&&!v.combined&&v.progress<.85){for(let i=0;i<Math.min(7,Math.ceil(v.butter*6));i++)marks+=`<rect x="${x(i)-6}" y="${y(i)-4}" width="12" height="8" rx="3" fill="#f9dfa0" opacity="${1-v.progress}"/>`;if(v.egg)marks+=`<ellipse cx="${x(4)}" cy="${y(4)}" rx="19" ry="10" fill="#f4bd55" opacity="${foodClamp(1-v.progress)}"/>`;if(v.milk)marks+=`<path d="M${180-v.rx*.65} ${v.cy}q${v.rx*.4} -15 ${v.rx} 1" fill="none" stroke="#fff8ed" stroke-width="6" opacity="${foodClamp(1-v.progress)}"/>`}if(v.moisture<.65&&v.kind!=='wet')for(let i=0;i<9;i++)marks+=`<path d="M${x(i)-9} ${y(i)}q7-6 15 1" stroke="${foodBlend(v.color,'#927052',.3)}" stroke-width="2" fill="none"/>`}
for(let i=0;i<v.chips;i++)marks+=`<path d="M${x(i+10)-3} ${y(i+10)-2}l5-2 3 4-6 2Z" fill="#674632"/>`;return `<defs class="batter-texture-defs"><clipPath id="${id}"><ellipse cx="180" cy="${v.cy}" rx="${v.rx}" ry="${v.ry}"/></clipPath></defs><g class="batter-texture" clip-path="url(#${id})">${marks}</g>`}
const emptyBowlRendering=mixtureBowl;
mixtureBowl=function(kind,smooth=false){let svg=emptyBowlRendering(kind,smooth);if(!state)return svg;const v=batterAppearance(kind,state);svg=svg.replace(/<ellipse[^>]*class="batter"[^>]*\/>/,`<ellipse cx="180" cy="${v.cy}" rx="${v.empty?124:v.rx}" ry="${v.empty?35:v.ry}" fill="${v.empty?(kind==='dry'?'#f8eaf0':'#dfeaf0'):v.color}" class="batter"/>`);svg=svg.replace('<g class="batterSwirl"',batterTextureSvg(v)+'<g class="batterSwirl"');svg=svg.replace('aria-hidden="true"',`role="img" aria-label="${esc(v.empty?'Empty '+kind+' bowl':kind+' mixture: '+v.texture)}" data-food-ingredients="${esc(JSON.stringify(v.a))}" data-batter-color="${v.color}" data-batter-texture="${v.texture}"`);if(!v.empty)svg=svg.replace('class="batterSwirl" opacity="0"','class="batterSwirl"');svg=svg.replace(/(<g class="batterSwirl"[^>]*>)[\s\S]*?(<\/g>)/,`$1${surfaceSwirl(v)}$2`);return svg}
function surfaceSwirl(v){if(v.empty)return '';return `<path d="M${180-v.rx*.6} ${v.cy}q${v.rx*.3} -${v.ry*.7} ${v.rx*.85} -${v.ry*.3}t-${v.rx*.25} ${v.ry*.65}" fill="none" stroke="${foodBlend(v.color,'#92704f',.27)}" stroke-width="3" opacity=".65"/>`}
function refreshBatterSurface(area,kind){const svg=area.querySelector('svg');if(!svg||!state)return;const v=batterAppearance(kind,state),old=Number(svg.dataset.foodProgress??-1);if(Math.abs(old-v.progress)<.045)return;svg.dataset.foodProgress=v.progress;svg.dataset.foodIngredients=JSON.stringify(v.a);svg.dataset.batterTexture=v.texture;svg.dataset.batterColor=v.color;svg.setAttribute('aria-label',kind+' mixture: '+v.texture);const surface=svg.querySelector('.batter');if(surface)surface.setAttribute('fill',v.empty?(kind==='dry'?'#f8eaf0':'#dfeaf0'):v.color);svg.querySelector('.batter-texture')?.remove();svg.querySelectorAll('.batter-texture-defs').forEach(e=>e.remove());const swirl=svg.querySelector('.batterSwirl');if(swirl){swirl.innerHTML=surfaceSwirl(v);swirl.insertAdjacentHTML('beforebegin',batterTextureSvg(v))}}
function bakeAppearance(s){const r=s.r,a=s.amounts||{},expected=Object.fromEntries([...r.dry,...r.wet].map(([n,v])=>[n,v]));const ratio=n=>(a[n]||0)/(expected[n]||1);const dry=ingredientVolume('Flour',a.Flour||0)+ingredientVolume('Cocoa',a.Cocoa||0),wet=ingredientVolume('Milk',a.Milk||0)+ingredientVolume('Egg',a.Egg||0)+.7*ingredientVolume('Butter',a.Butter||0)+ingredientVolume('Lemon juice',a['Lemon juice']||0);const needDry=ingredientVolume('Flour',expected.Flour||0)+ingredientVolume('Cocoa',expected.Cocoa||0),needWet=ingredientVolume('Milk',expected.Milk||0)+ingredientVolume('Egg',expected.Egg||0)+.7*ingredientVolume('Butter',expected.Butter||0)+ingredientVolume('Lemon juice',expected['Lemon juice']||0);const moisture=(wet/(dry+.04))/(needWet/(needDry+.04)||1),lift=(a['Baking powder']||0)*.5+(a['Baking soda']||0)*.25,needLift=(expected['Baking powder']||0)*.5+(expected['Baking soda']||0)*.25,liftRatio=needLift?lift/needLift:lift>0?3:1;const fold=s.foldStirs??s.mix/r.mix??0,heat=(s.bakeProgress||0)/r.time*Math.pow((s.temp||r.temp)/r.temp,2);const browningHeat=heat*(.75+.25*foodClamp(ratio('Sugar'),0,3));const burned=browningHeat>1.22,raw=heat<.82,sunken=moisture>1.5||liftRatio>2||raw,parched=ratio('Flour')>1.3||moisture<.64||heat>1.18,lumpy=fold<.85||(s.dryStirs??1)<.7,greasy=ratio('Butter')>1.4;let rise=foodClamp(1-foodClamp(1-liftRatio)*.46-Math.max(0,fold-1.15)*.15-(moisture>1.5?.22:0)-(raw?.13:0)-(liftRatio>2?.22:0),.43,1.12);let color=batterAppearance('combined',{...s,combined:false}).color;color=foodBlend(color,(a.Cocoa||0)>0?'#775039':'#d9a36b',foodClamp((browningHeat-.25)*.65));if(burned)color=foodBlend(color,'#5c3524',foodClamp((browningHeat-1.05)*1.5));if(raw)color=foodBlend(color,'#f4e3b9',.35);const flags=[rise<.8?'flat and dense':null,burned?'dark scorched edges':null,raw?'pale underbaked center':null,sunken?'sunken center':null,parched?'dry cracked crust':null,lumpy?'unmixed flour patches':null,greasy?'greasy sheen':null].filter(Boolean);return {color,rise,burned,raw,sunken,parched,lumpy,greasy,moisture,heat,chips:Math.min(22,Math.round((a['Chocolate chips']||0)*2)),spread:foodClamp(1+(ratio('Butter')-1)*.16-(ratio('Flour')-1)*.12,.75,1.25),description:flags.length?flags.join(', '):'even rise and golden tender crumb',flags}}
function foodClip(shape,marks){const id='bakesurface'+illustrationId++;return `<defs><clipPath id="${id}">${shape}</clipPath></defs><g clip-path="url(#${id})">${marks}</g>`}
function bakedTexture(v,cx=0,cy=0,rx=55,ry=22){let marks='';if(v.burned)marks+=`<ellipse cx="${cx}" cy="${cy}" rx="${rx}" ry="${ry}" fill="none" stroke="#613b2b" stroke-width="7" opacity=".8"/>`;if(v.raw||v.sunken)marks+=`<ellipse cx="${cx}" cy="${cy}" rx="${rx*.47}" ry="${ry*.55}" fill="${foodBlend(v.color,'#73513d',.25)}" opacity=".85"/><path d="M${cx-rx*.25} ${cy-ry*.18}q${rx*.25} -5 ${rx*.48} 0" stroke="#fff4cf" stroke-width="3" opacity=".45" fill="none"/>`;if(v.parched){for(let i=0;i<4;i++){const x=cx-rx*.6+i*rx*.4,y=cy+Math.sin(i*2)*ry*.35;marks+=`<path d="M${x} ${y-5}l4 4-6 4 8 4" fill="none" stroke="${foodBlend(v.color,'#563b2b',.5)}" stroke-width="1.8"/>`}}if(v.lumpy){for(let i=0;i<5;i++)marks+=`<ellipse cx="${cx+Math.cos(i*2.4)*rx*.6}" cy="${cy+Math.sin(i*2.4)*ry*.5}" rx="${5+i%3}" ry="3" fill="#f7edd8" opacity=".85"/>`}if(v.greasy)marks+=`<path d="M${cx-rx*.6} ${cy}q${rx*.4} -${ry} ${rx*.9} -3" fill="none" stroke="#fce7ab" stroke-width="5" opacity=".48"/>`;return marks}
const recipePreviewArt=art;
art=function(r,quality=1,frost=null,preview=false){if(preview||!state||state.r!==r||state.stage<7)return recipePreviewArt(r,1,frost);const v=bakeAppearance(state),shape=state.pan?.shape||r.id,cream=icingColor(frost||'Vanilla');let body='';const chipMarks=(cx,cy,n,rx=27,ry=21)=>Array.from({length:n},(_,i)=>{const x=cx+Math.cos(i*2.4)*rx*(.3+i%3*.22),y=cy+Math.sin(i*2.4)*ry*(.4+i%2*.35);return `<path d="M${x-3} ${y-3}l6-1 2 5-6 2Z" fill="#614332"/>`}).join('');
if(shape==='cookie'){body=[[-40,-20],[34,-25],[0,35]].map(([x,y])=>`<g transform="translate(${x} ${y}) scale(${v.spread} ${v.rise/v.spread})"><ellipse cy="5" rx="38" ry="32" fill="${foodBlend(v.color,'#765035',.35)}"/><ellipse rx="38" ry="32" fill="url(#PAINT)" stroke="${v.burned?'#543224':'#be9165'}" stroke-width="${v.burned?5:1.5}"/>${bakedTexture(v,0,0,34,28)}${chipMarks(0,0,v.chips)}${frost?`<path d="M-25-5q10-12 13 0t13 0t13 0" fill="none" stroke="${cream}" stroke-width="4"/>`:''}</g>`).join('')}
else if(shape==='cupcake'){const top=12+(1-v.rise)*30;body=`<path d="M-47 ${top}q47-10 94 0l-12 58q-35 14-70 0Z" fill="#dba2b8" stroke="#bf8fa5" stroke-width="1.5"/><path d="M-28 ${top+12}l7 40M-10 ${top+14}l2 40M10 ${top+14}l-2 40M28 ${top+12}l-7 40" stroke="#f5d5df" stroke-width="5"/><path d="M-47 ${top}Q-42 ${top-47*v.rise} 0 ${top-48*v.rise}Q42 ${top-47*v.rise} 47 ${top}Q0 ${top+25}-47 ${top}Z" fill="url(#PAINT)" stroke="${v.burned?'#603b2b':'#c19465'}" stroke-width="${v.burned?4:1.5}"/>${bakedTexture(v,0,top-7,39,20)}${chipMarks(0,top-10,Math.min(v.chips,10),29,14)}${frost?`<g transform="translate(0 ${top-48*v.rise+20})"><path d="M-44 7C-57-8-31-15-26-16C-35-32-7-35-3-39C-7-49 5-59 10-63C6-47 36-42 28-25C53-16 55-1 43 8Q0 22-44 7Z" fill="${cream}" stroke="#ba9894" stroke-width="1.2"/></g>`:''}`}
else if(shape==='brownie'){const h=45*v.rise;body=`<path d="M-65-23L22-48 68-16 65 ${h} -20 ${h+24}-65 ${h-9}Z" fill="${foodBlend(v.color,'#5b3828',.35)}" stroke="${v.burned?'#41291f':'#947050'}" stroke-width="2"/><path d="M-65-23L22-48 68-16-20 9Z" fill="url(#PAINT)"/>${foodClip('<path d="M-65-23L22-48 68-16-20 9Z"/>',bakedTexture(v,0,-20,52,22)+chipMarks(0,-20,Math.min(v.chips,14),45,17))}${frost?`<path d="M-42-22q20-14 18 0t20 0t20 0" stroke="${cream}" stroke-width="5" fill="none"/>`:''}`}
else if(shape==='lemon'){const top=-5-(v.rise*35);body=`<path d="M-68 ${top+15}Q-68 ${top-6}-39 ${top}l84 8q24 3 24 26l-7 42q-2 12-16 12l-94-9q-17-1-18-17Z" fill="url(#PAINT)" stroke="${v.burned?'#513526':'#c1976b'}" stroke-width="2"/>${bakedTexture(v,0,top+16,56,18)}${chipMarks(0,top+16,Math.min(v.chips,12),45,12)}${frost?`<path d="M-66 ${top+13}q5-23 28-17l82 9q24 3 23 23q-9 12-17 0q-9-8-16 7q-10 12-18-6q-8-9-18 0q-13 10-23-4q-10-9-22-2Z" fill="${cream}" opacity=".94"/>`:''}`}
else{const top=49-73*v.rise;body=`<path d="M-64 ${top}H64v${49-top}q-64 28-128 0Z" fill="url(#PAINT)" stroke="${v.burned?'#543425':'#c49975'}" stroke-width="2"/><path d="M-64 ${top+(49-top)*.5}q64 21 128 0v10q-64 23-128 0Z" fill="#f2c3cf"/><ellipse cy="${top}" rx="64" ry="22" fill="${v.color}"/>${bakedTexture(v,0,top,60,20)}${frost?`<ellipse cy="${top}" rx="64" ry="22" fill="${cream}"/><path d="M-64 ${top}v17q8 10 15-2v-8q9 16 18 2q10-11 16 3q9 16 18-2q8-14 16 0q8 11 17-2q10-11 17 2q11 11 11-11v-1" fill="${cream}"/>`:''}`}
if(v.overflow)body+=shape==='cupcake'?`<path d="M-46 12q-18 13-2 18q48 12 96 0q16-5-2-18q-46 13-92 0Z" fill="${v.color}" stroke="${foodBlend(v.color,'#73513d',.25)}" stroke-width="1.5"/>`:`<ellipse cx="14" cy="72" rx="72" ry="8" fill="${v.color}" opacity=".8"/>`;if(v.parched||v.burned)body+=Array.from({length:9},(_,i)=>`<ellipse cx="${-70+i*17}" cy="${70+(i%3)*3}" rx="${2+i%2}" ry="1.7" fill="${foodBlend(v.color,'#5e3b27',.3)}"/>`).join('');let svg=softSvg(`<ellipse cy="78" rx="88" ry="10" fill="#96724d18"/>${body}`,r.name+': '+v.description,'-108 -98 216 196',[foodBlend(v.color,'#fff4ce',.22),v.color]);return svg.replace('<svg ',`<svg data-food-rise="${v.rise.toFixed(2)}" data-food-color="${v.color}" data-food-defects="${v.flags.join('|')}" `)};
function refreshOvenAppearance(){const food=document.querySelector('.oven-bake');if(food&&state){const bake=food.querySelector('.inoven-food');if(bake)bake.innerHTML=art(state.r);else food.innerHTML=art(state.r)}}
